#include <stdio.h>
#include <string.h>
/* ex04：三种基带编码的波形对比
 * NRZ（不归零）        ：1 -> 高电平，0 -> 低电平；连续相同位没有跳变
 * 曼彻斯特（以太网用） ：每位中间必有一次跳变，0 = 高->低，1 = 低->高
 *                        自带时钟（自同步），但带宽利用率只有 50%
 * 差分曼彻斯特       ：每位中间也跳变，但「位开始处有无跳变」表示 0/1
 *                        抗极性反转（线接反了也能收）
 * 本程序把三种编码的电平序列打印成 ASCII 波形。*/
static void wave(const char *name, const int *lv, int n, const char *bs) {
    printf("\n%s\n", name);
    /* 每比特占 2 格：# 表示高电平，空格表示低电平（用 ASCII 才能保证列严格对齐） */
    printf("  高 |");
    for (int i = 0; i < n; i++) printf("%s", lv[i] ? "##" : "  ");
    printf("|\n  低 |");
    for (int i = 0; i < n; i++) printf("%s", lv[i] ? "  " : "##");
    printf("|\n     ");
    for (int i = 0; bs[i] != '\0'; i++) printf("%c   ", bs[i]);
    printf("<- 比特序列（每比特 2 个码元 = 4 格）\n");
}

int main(void) {
    const char *bits = "1011001";
    int n = (int)strlen(bits);
    int nrz[16], man[16], dman[16];

    /* NRZ */
    for (int i = 0; i < n; i++) {
        nrz[2 * i] = nrz[2 * i + 1] = (bits[i] == '1');
    }
    /* 曼彻斯特：0 = 高->低，1 = 低->高 */
    for (int i = 0; i < n; i++) {
        if (bits[i] == '0') { man[2 * i] = 1; man[2 * i + 1] = 0; }
        else                { man[2 * i] = 0; man[2 * i + 1] = 1; }
    }
    /* 差分曼彻斯特：位开始处「有跳变=0，无跳变=1」，位中间必跳变 */
    int prev = 0;                     /* 上一比特结束时的电平 */
    for (int i = 0; i < n; i++) {
        int start = (bits[i] == '0') ? !prev : prev;   /* 0 则翻转，1 则保持 */
        dman[2 * i] = start;
        dman[2 * i + 1] = !start;                      /* 中间必跳 */
        prev = dman[2 * i + 1];
    }

    printf("比特序列: %s（每比特 2 格，便于观察位中间跳变）\n", bits);
    wave("NRZ（不归零）", nrz, 2 * n, bits);
    wave("曼彻斯特（0=高->低, 1=低->高）", man, 2 * n, bits);
    wave("差分曼彻斯特（位首有跳变=0, 无跳变=1）", dman, 2 * n, bits);

    printf("\n结论：\n");
    printf("  1) NRZ 连续相同位时电平不变 —— 接收方无法从信号里提取时钟，\n");
    printf("     长串 0 或 1 会导致「时钟漂移」而失步；\n");
    printf("  2) 曼彻斯特每位中间必跳变，跳变本身就是时钟，故「自同步」；\n");
    printf("     代价是波特率翻倍（1 bit 要 2 个码元），带宽利用率仅 50%%；\n");
    printf("  3) 差分曼彻斯特看「位首有无跳变」，所以双绞线接反了也能正确解码。\n");
    return 0;
}
